-- Pilot 的 HTTPS、WebSocket、JSBridge，以及机场回答设备的上传凭证和航线文件地址。
-- 每条指令自带通讯方式。HTTP 方法和路径只写在 HTTPS 指令上。
-- 每条指令有一条适用手段为无人机的动作，并在指令协议对接里对上。不从东古操作码翻译。
SET search_path TO dynamicbusiness, public;

BEGIN;

INSERT INTO dynamic_model_field_assignment (
  model_id, field_id, model_code, field_code, required, is_searchable, is_filterable, is_sortable,
  sort, field_source, tenant_id, creator
)
SELECT m.id, f.id, m.code, f.code, false, true, true, false, v.sort_order, 'CUSTOM', 1, 'seed'
FROM (VALUES
  ('data_protocol_dji_pilot_https', 'http_method', 22),
  ('data_protocol_dji_pilot_https', 'http_path', 23)
) AS v(model_code, field_code, sort_order)
JOIN dynamic_model m ON m.deleted = false AND m.tenant_id = 1 AND m.code = v.model_code
JOIN dynamic_field f ON f.deleted = false AND f.tenant_id = 1 AND f.code = v.field_code
ON CONFLICT (model_code, field_code, tenant_id) WHERE deleted = false
DO UPDATE SET field_id = EXCLUDED.field_id, sort = EXCLUDED.sort, deleted = false, updater = 'seed', update_time = CURRENT_TIMESTAMP;

CREATE TEMP TABLE dji_channel_command (
  model_code text,
  protocol_version text,
  code text,
  name text,
  action_code text,
  mapping_code text,
  communication text,
  channel text,
  topic text,
  http_method text,
  http_path text,
  custom_fields jsonb
) ON COMMIT DROP;

