INSERT INTO ent_data_protocol_t1 (
  tenant_id, entity_type_code, model_id, name, code, status, custom_fields, command_direction, creator, deleted
)
SELECT 1, 'data_protocol', m.id, c.name, c.code, 1, c.custom_fields, 'downlink', 'seed', false
FROM dji_channel_command c
JOIN dynamic_model m ON m.deleted = false AND m.tenant_id = 1 AND m.code = c.model_code
WHERE NOT EXISTS (
  SELECT 1 FROM ent_data_protocol_t1 e
  WHERE e.tenant_id = 1 AND e.code = c.code AND e.deleted = false
);

UPDATE ent_data_protocol_t1 e
SET name = c.name, model_id = m.id, command_direction = 'downlink', status = 1, deleted = false,
    custom_fields = c.custom_fields, updater = 'seed', update_time = CURRENT_TIMESTAMP
FROM dji_channel_command c
JOIN dynamic_model m ON m.deleted = false AND m.tenant_id = 1 AND m.code = c.model_code
WHERE e.tenant_id = 1 AND e.code = c.code;

INSERT INTO dynamic_entity_category_relation_t1 (
  tenant_id, category_id, entity_type_code, entity_id, domain, sort, creator, deleted
)
SELECT 1, cat.id, 'data_protocol', e.id, NULL, 0, 'seed', false
FROM dji_channel_command c
JOIN ent_data_protocol_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.code
JOIN dynamic_category cat ON cat.deleted = false AND cat.tenant_id = 1 AND cat.code = 'cat-protocol-dji-uav'
WHERE NOT EXISTS (
  SELECT 1 FROM dynamic_entity_category_relation_t1 r
  WHERE r.tenant_id = 1 AND r.entity_type_code = 'data_protocol'
    AND r.entity_id = e.id AND r.category_id = cat.id
);

-- 动作是一套标准，不按协议各建一份。指令留在协议型号上，对照写在标准动作上。

INSERT INTO dynamic_entity_field_index_t1 (
  entity_id, model_id, field_code, value_string, value_number, creator, tenant_id, deleted
)
SELECT e.id, e.model_id, v.field_code, NULLIF(v.value_string, ''), NULL, 'seed', 1, false
FROM dji_channel_command c
JOIN ent_data_protocol_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.code
CROSS JOIN LATERAL (VALUES
  ('communication_protocol', NULLIF(c.communication, '')),
  ('protocol_channel', NULLIF(c.channel, '')),
  ('mqtt_topic', NULLIF(c.topic, '')),
  ('http_method', NULLIF(c.http_method, '')),
  ('http_path', NULLIF(c.http_path, '')),
  ('protocol_version', NULLIF(c.protocol_version, ''))
) AS v(field_code, value_string)
WHERE v.value_string IS NOT NULL
AND NOT EXISTS (
  SELECT 1 FROM dynamic_entity_field_index_t1 idx
  WHERE idx.deleted = false AND idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = v.field_code
);

UPDATE dynamic_entity_field_index_t1 idx
SET value_string = v.value_string, model_id = e.model_id, deleted = false, updater = 'seed', update_time = CURRENT_TIMESTAMP
FROM dji_channel_command c
JOIN ent_data_protocol_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.code
CROSS JOIN LATERAL (VALUES
  ('communication_protocol', NULLIF(c.communication, '')),
  ('protocol_channel', NULLIF(c.channel, '')),
  ('mqtt_topic', NULLIF(c.topic, '')),
  ('http_method', NULLIF(c.http_method, '')),
  ('http_path', NULLIF(c.http_path, '')),
  ('protocol_version', NULLIF(c.protocol_version, ''))
) AS v(field_code, value_string)
WHERE idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = v.field_code AND v.value_string IS NOT NULL;

INSERT INTO dynamic_entity_field_index_t1 (
  entity_id, model_id, field_code, value_string, value_number, creator, tenant_id, deleted
)
SELECT e.id, e.model_id, 'action_ref', NULL, a.id, 'seed', 1, false
FROM dji_channel_command c
JOIN ent_protocol_mapping_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.mapping_code
JOIN ent_action_t1 a ON a.deleted = false AND a.tenant_id = 1 AND a.code = c.action_code
WHERE NOT EXISTS (
  SELECT 1 FROM dynamic_entity_field_index_t1 idx
  WHERE idx.deleted = false AND idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = 'action_ref'
);

UPDATE dynamic_entity_field_index_t1 idx
SET value_number = a.id, value_string = NULL, deleted = false, updater = 'seed', update_time = CURRENT_TIMESTAMP
FROM dji_channel_command c
JOIN ent_protocol_mapping_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.mapping_code
JOIN ent_action_t1 a ON a.deleted = false AND a.tenant_id = 1 AND a.code = c.action_code
WHERE idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = 'action_ref';

INSERT INTO dynamic_entity_field_index_t1 (
  entity_id, model_id, field_code, value_string, value_number, creator, tenant_id, deleted
)
SELECT e.id, e.model_id, 'mapped_protocol_version', c.protocol_version, NULL, 'seed', 1, false
FROM dji_channel_command c
JOIN ent_protocol_mapping_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.mapping_code
WHERE NOT EXISTS (
  SELECT 1 FROM dynamic_entity_field_index_t1 idx
  WHERE idx.deleted = false AND idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = 'mapped_protocol_version'
);

UPDATE dynamic_entity_field_index_t1 idx
SET value_string = c.protocol_version, deleted = false, updater = 'seed', update_time = CURRENT_TIMESTAMP
FROM dji_channel_command c
JOIN ent_protocol_mapping_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.mapping_code
WHERE idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = 'mapped_protocol_version';

INSERT INTO dynamic_entity_field_index_t1 (
  entity_id, model_id, field_code, value_string, value_number, creator, tenant_id, deleted
)
SELECT e.id, e.model_id, 'protocol_instruction_ref', NULL, p.id, 'seed', 1, false
FROM dji_channel_command c
JOIN ent_protocol_mapping_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.mapping_code
JOIN ent_data_protocol_t1 p ON p.deleted = false AND p.tenant_id = 1 AND p.code = c.code
WHERE NOT EXISTS (
  SELECT 1 FROM dynamic_entity_field_index_t1 idx
  WHERE idx.deleted = false AND idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = 'protocol_instruction_ref'
);

UPDATE dynamic_entity_field_index_t1 idx
SET value_number = p.id, value_string = NULL, deleted = false, updater = 'seed', update_time = CURRENT_TIMESTAMP
FROM dji_channel_command c
JOIN ent_protocol_mapping_t1 e ON e.deleted = false AND e.tenant_id = 1 AND e.code = c.mapping_code
JOIN ent_data_protocol_t1 p ON p.deleted = false AND p.tenant_id = 1 AND p.code = c.code
WHERE idx.tenant_id = 1 AND idx.entity_id = e.id AND idx.field_code = 'protocol_instruction_ref';

-- 上一版把 WebSocket 业务码收成了小写。正确业务码会写成新指令，这里停用旧编码。
UPDATE ent_data_protocol_t1 e
SET deleted = true, updater = 'seed', update_time = CURRENT_TIMESTAMP
WHERE e.tenant_id = 1 AND e.deleted = false
  AND e.code LIKE 'proto-dji-pilot-ws-%'
  AND NOT EXISTS (SELECT 1 FROM dji_channel_command c WHERE c.code = e.code);

UPDATE ent_action_t1 a
SET deleted = true, updater = 'seed', update_time = CURRENT_TIMESTAMP
WHERE a.tenant_id = 1 AND a.deleted = false
  AND a.code LIKE 'act-dji-pilot-ws-%'
  AND NOT EXISTS (SELECT 1 FROM dji_channel_command c WHERE c.action_code = a.code);

UPDATE ent_protocol_mapping_t1 e
SET deleted = true, updater = 'seed', update_time = CURRENT_TIMESTAMP
WHERE e.tenant_id = 1 AND e.deleted = false
  AND e.code LIKE 'map-dji-pilot-ws-%'
  AND NOT EXISTS (SELECT 1 FROM dji_channel_command c WHERE c.mapping_code = e.code);

-- 大疆两个型号的详情要能填写 HTTP 方法和路径。东古和机器人的现有指令走 WebSocket，不挂这两项。
UPDATE model_crud_form_definition form
SET crud_form_fields = jsonb_set(
      form.crud_form_fields,
      '{customFieldDefs}',
      (
        SELECT COALESCE(jsonb_agg(elem ORDER BY (elem->>'sort')::int), '[]'::jsonb)
        FROM (
          SELECT elem
          FROM jsonb_array_elements(COALESCE(form.crud_form_fields->'customFieldDefs', '[]'::jsonb)) elem
          WHERE elem->>'fieldCode' NOT IN ('http_method', 'http_path')
          UNION ALL
          SELECT jsonb_build_object(
            'sort', CASE d.code WHEN 'http_method' THEN 22 ELSE 23 END,
            'label', d.name,
            'fieldId', d.id,
            'fieldKey', d.code,
            'renderAs', 'input',
            'required', false,
            'baseField', false,
            'fieldCode', d.code,
            'fieldName', d.name,
            'fieldType', d.type,
            'fieldSource', 'CUSTOM',
            'semanticType', d.code
          )
          FROM dynamic_field d
          WHERE d.deleted = false AND d.tenant_id = 1 AND d.code IN ('http_method', 'http_path')
        ) defs(elem)
      ),
      true
    ),
    updater = 'seed',
    update_time = CURRENT_TIMESTAMP
FROM dynamic_model m
WHERE form.deleted = false
  AND form.tenant_id = 1
  AND form.model_id = m.id
  AND m.code IN ('data_protocol_dji_dock', 'data_protocol_dji_pilot');

UPDATE model_crud_form_definition form
SET crud_form_fields = jsonb_set(
      form.crud_form_fields,
      '{formLayout,panels}',
      (
        SELECT COALESCE(jsonb_agg(
          CASE
            WHEN panel ? 'fieldKeys' THEN
              jsonb_set(
                panel,
                '{fieldKeys}',
                (
                  SELECT COALESCE(jsonb_agg(key ORDER BY ord), '[]'::jsonb)
                  FROM (
                    SELECT key, ord
                    FROM jsonb_array_elements_text(panel->'fieldKeys') WITH ORDINALITY AS listed(key, ord)
                    UNION ALL
                    SELECT extra.key, 2000 + extra.ord
                    FROM (VALUES ('http_method', 1), ('http_path', 2)) AS extra(key, ord)
                    WHERE NOT EXISTS (
                      SELECT 1
                      FROM jsonb_array_elements_text(panel->'fieldKeys') existing(key)
                      WHERE existing.key = extra.key
                    )
                  ) keys
                )
              )
            ELSE panel
          END
        ), '[]'::jsonb)
        FROM jsonb_array_elements(form.crud_form_fields->'formLayout'->'panels') panel
      ),
      true
    ),
    updater = 'seed',
    update_time = CURRENT_TIMESTAMP
FROM dynamic_model m
WHERE form.deleted = false
  AND form.tenant_id = 1
  AND form.model_id = m.id
  AND m.code IN ('data_protocol_dji_dock', 'data_protocol_dji_pilot')
  AND form.crud_form_fields ? 'formLayout';

COMMIT;
